from fastapi import APIRouter
from pydantic import BaseModel

router = APIRouter(prefix="/drink", tags=["Drink Chatbot"])

class ChatRequest(BaseModel):
    message: str

@router.get("/ping")
def ping():
    return {"status": "ok", "message": "음료 챗봇 서버가 정상 작동 중입니다!"}

@router.post("/chat")
def chat(request: ChatRequest):
    user_msg = request.message
    # [임시 테스트 응답] 나중에 여기에 OpenAI나 LLM 로직을 연결합니다.
    bot_reply = f"음료 챗봇입니다. '{user_msg}'에 맞는 음료를 추천해 드릴게요! (예: 시원한 아이스 아메리카노)"
    return {"reply": bot_reply}

from fastapi import FastAPI
from drink.router import router as drink_router

# Nginx에서 /chatbot 경로로 들어오므로 root_path 지정
app = FastAPI(
    title="통합 챗봇 API",
    root_path="/chatbot"
)

# drink 챗봇 라우터 등록
app.include_router(drink_router)

@app.get("/")
def read_root():
    return {"service": "챗봇 메인 게이트웨이", "version": "1.0"}

server {
    listen 80;
    server_name _;

    # 1. 프론트엔드 화면 (루트 경로)
    location / {
        # 개발 중일 땐 Vite 개발서버로 프록시
        proxy_pass http://127.0.0.1:5173;
        proxy_set_header Host $host;
    }

    # 2. 백엔드 API (/api로 시작하는 요청)
    location /api/ {
        # 백엔드 FastAPI 내부 포트로 토스
        proxy_pass http://127.0.0.1:8000/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }
}

server {
    listen 80 default_server;
    listen [::]:80 default_server;

    server_name _;

    # 1. 기본 웹 화면 요청
    location / {
        root /var/www/html;
        index index.html index.htm;
        try_files $uri $uri/ =404;
    }

    # 2. 백엔드 API 요청 (/api/로 시작하는 주소)
    location /api/ {
        # 외부 요청을 내부의 백엔드 포트(8000)로 은밀하게 전달
        proxy_pass http://127.0.0.1:8000/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }
}

server {
    listen 80 default_server;
    listen [::]:80 default_server;

    server_name _;

    # 1. 기본 웹 화면 요청
    location / {
        root /var/www/html;
        index index.html index.htm;
        # 새로고침 시 404 에러 방지 (React 필수 설정)
        try_files $uri $uri/ /index.html;
    }

    # 2. 백엔드 API 요청 (/api/로 시작하는 주소)
    location /api/ {
        # 끝에 슬래시(/)를 빼야 /api 주소가 FastAPI(main.py)로 온전히 전달됩니다!
        proxy_pass http://127.0.0.1:8000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}
